/* Aligns a HUD element's anchor by its flags (+0x60): unless bit 0 or 1
   is set, *Y moves up by half the height (+0x5C); unless bit 2 is set,
   *X moves left by the width (+0x58) with bit 3, else by half of it.
   Returns 0. The flags are read once for the first test and again after
   the store; `(flags ^ 1) & 1` is retail's xori / andi test of bit 0. */
int hud_screen_position(HudElem *rec, int *x, int *y) {
    int w = rec->w;
    int h = rec->h;
    int flags = rec->flags;

    if ((flags ^ 1) & 1) {
        if (!(flags & 2)) {
            *y -= h >> 1;
        }
    }
    if (!(rec->flags & 4)) {
        if (rec->flags & 8) {
            *x -= w;
        } else {
            *x -= w >> 1;
        }
    }
    return 0;
}

extern int truncate_float_to_s32(float);
extern float hud_slide_timer_active_scales[];
extern float hud_slide_timer_inactive_scales[];

/* Slides a HUD element in or out from its anchored edge: step T moves by
   D (back while the timer +0x7C runs, forward otherwise), clamped to
   0..23, picks a ramp value from hud_slide_timer_active_scales (timer running) or
   hud_slide_timer_inactive_scales, and offsets *Y by it times (height + 52) for flags 1
   (up) / 2 (down), or *X by it times (width + 20) for flags 4 (left) /
   8 (right), rounded (IntToFloat / truncate_float_to_s32 convert). */
void apply_hud_slide_offset(HudElem *e, int *x, int *y, int t, int d) {
    int dx = 0;
    int dy = 0;
    float s;

    if (e->unk7C != 0) {
        t -= d;
    } else {
        t += d;
    }
    if (t < 0) {
        t = 0;
    }
    if (t > 23) {
        t = 23;
    }
    if (e->unk7C != 0) {
        s = hud_slide_timer_active_scales[t];
    } else {
        s = hud_slide_timer_inactive_scales[t];
    }
    if (e->flags & 1) {
        dy = -truncate_float_to_s32(s * (IntToFloat(e->h) + 52.0f) + 0.5f);
    } else if (e->flags & 2) {
        dy = truncate_float_to_s32(s * (IntToFloat(e->h) + 52.0f) + 0.5f);
    } else if (e->flags & 4) {
        dx = -truncate_float_to_s32(s * (IntToFloat(e->w) + 20.0f) + 0.5f);
    } else if (e->flags & 8) {
        dx = truncate_float_to_s32(s * (IntToFloat(e->w) + 20.0f) + 0.5f);
    }
    *x += dx;
    *y += dy;
}
/* updates numeric HUD values and dimensions from digit count */
void initialize_numeric_hud_values_and_dimensions(HudElem *e) {
    int *value = e->unk0C;
    int digits;
    int v, flags, width;
    if (value && !((int)value & 3)) {
        e->unk78 = *value;
        if (e->unk08 < e->unk78)
            e->unk78 = e->unk08;
        e->unk74 = e->unk78;
    } else {
        e->unk78 = 99999;
        e->unk74 = 99999;
    }
    v = e->unk08;
    digits = 0;
    flags = e->flags;
    width = e->h;
    while (v >= 10) {
        v /= 10;
        digits++;
    }
    if (!(flags & 3) && (flags & 12)) {
        e->h = width + (digits + 1) * 12;
        if (e->w < 14)
            e->w = 14;
    } else {
        if (width < 12)
            e->h = 12;
        e->w += (digits + 1) * 14;
    }
}
