/* Resets a HUD element: a timer of 30 + scale_ticks(180) (+0x7C),
   offsets 0x48 / 0x4A cleared, then initialize_numeric_hud_values_and_dimensions. */
void reset_numeric_hud_element(HudElem *e) {
    e->unk7C = scale_ticks(0xB4) + 0x1E;
    e->unk48 = 0;
    e->unk4A = 0;
    initialize_numeric_hud_values_and_dimensions(e);
}
