/* Draw the fading HUD text panel, plus the best race time and score near the race start points. */
int draw_hud_text_panel(char *e) {
    int w1, tex, l1, y, i, width, left, w2, l2, alpha, color, c, level, elapsed, score, interval, per, seconds, minutes,
        rem, idx;
    float fade;
    HudPoint points[2];
    HudPoint point;
    char text[64];
    int text_y;
    void *pt;
    unsigned char *opacity = (unsigned char *)e + 0x70;

    if (pal_mode != 0) {
        y = hud_text_panel_y + 0xa;
    } else {
        y = hud_text_panel_y + 0x12;
    }
    fade = IntToFloat(*opacity);
    fade /= multiply_global_factor(8.0f);
    if (fade < 0.0f)
        fade = 0.0f;
    if (fade > 1.0f)
        fade = 1.0f;
    text_y = y + 8;
    i = 0;
    alpha = truncate_float_to_s32(fade * 128.0f);
    color = (alpha << 24) | 0x40f040;
    if (hud_text_panel_string[0] >= 2) {
        do {
            i++;
        } while (hud_text_panel_string[i] >= 2 && i < 0x80);
    }
    if (hud_text_panel_string[i] == 1) {
        hud_text_panel_string[i] = 0;
        w1 = measure_text_width_regular((const char *)hud_text_panel_string, -1);
        l1 = 0xe0 - (w1 >> 1);
        w2 = measure_text_width_regular((const char *)&hud_text_panel_string[1] + i, -1);
        l2 = 0xe0 - (w2 >> 1);
        if (l1 >= l2) {
            left = l2;
            width = w2;
        } else {
            left = l1;
            width = w1;
        }
        draw_hud_sprite(GetIconFrame(0x7580, 0), left + 0x20, y, width, 0x36, alpha);
        c = color;
        draw_hud_sprite(GetIconFrame(0x7580, 1), left, y, 0x20, 0x36, alpha);
        tex = GetIconFrame(0x7580, 1);
        {
            int t = width + 0x20;
            draw_hud_sprite_flipped(tex, left + t, y, 0x20, 0x36, alpha);
        }
        FontPrintCenter(0x100, text_y, c, hud_text_panel_string, -1);
        FontPrintCenter(0x100, y + 0x1b, c, &hud_text_panel_string[1] + i, -1);
    } else {
        int w, x;
        w = measure_text_width_regular((const char *)hud_text_panel_string, -1);
        x = 0xe0 - (w >> 1);
        draw_hud_sprite(GetIconFrame(0x7580, 1), x, y, 0x20, 0x20, alpha);
        draw_hud_sprite(GetIconFrame(0x7580, 0), x + 0x20, y, w, 0x20, alpha);
        tex = GetIconFrame(0x7580, 1);
        {
            int t = w + 0x20;
            draw_hud_sprite_flipped(tex, x + t, y, 0x20, 0x20, alpha);
        }
        FontPrintCenter(0x100, text_y, color, hud_text_panel_string, -1);
    }
    level = g_current_level_index;
    if (level == 5 || level == 0x10) {
        typedef unsigned int quadword __attribute__((mode(TI), aligned(16)));
        *(quadword *)&points[0] = 0;
        *(quadword *)&points[1] = 0;
        points[0].x = 294.5f;
        points[0].y = 225.4f;
        points[0].z = 100.0f;
        points[1].x = 115.7f;
        points[1].y = 287.0f;
        points[1].z = 119.5f;
        if (level == 5) {
            qcopy(&point, &points[0]);
        } else {
            qcopy(&point, &points[1]);
        }
        pt = &point;
        if (fast_vec_dist(hero_pos, pt) < 5.0f) {
            race_record_panel_end_y = y + 100;
            elapsed = race_best_times[g_current_level_index == LEVEL_KALEBO3 ? 1 : 0];
            score = race_best_records[g_current_level_index == LEVEL_KALEBO3 ? 1 : 0];
            if (elapsed != 0) {
                interval = pal_mode != 0 ? 3000 : 3600;
                per = interval / 60;
                seconds = elapsed / interval;
                rem = elapsed - seconds * interval;
                minutes = rem / per;
                rem = (rem - minutes * per) * 100 / per;
                sprintf(text, hud_text_panel_time_format, msg_string(0x5320), seconds, minutes, rem);
                draw_framed_text(0x100, y + 0x28, color, text);
                if (score != 0) {
                    sprintf(text, hud_text_panel_score_format, msg_string(0x5321), score);
                    draw_framed_text(0x100, y + 0x48, color, text);
                }
            }
        }
    }
    return *(int *)(e + 0x58);
}
