/* Draws a HUD gauge frame. */
int hud_draw_gauge_frame(HudElem *e) {
    int pos[2];
    int left, top, right, bottom, w, h, bh, step, i;
    {
        int ww = hud_stars_width;
        pos[0] = e->unk50;
        pos[1] = e->unk54;
        e->w = ww;
        {
            int *src = &hud_star_height;
            int *dst = &e->h;
            __builtin_memcpy(dst, src, 4);
        }
    }
    hud_screen_position(e, &pos[0], &pos[1]);
    apply_hud_slide_offset(e, &pos[0], &pos[1], e->unk6C, 0);
    w = hud_stars_width * 0xD0;
    h = hud_star_height * 0xA0;
    bh = hud_stars_width * 0x260;
    bottom = hud_star_height * 0xEA0;
    left = (pos[0] + e->unk48) << 4;
    top = (pos[1] + e->unk4A) << 4;
    left += w / 64;
    top += h / 256;
    right = left + bh / 64;
    bottom = top + bottom / 256;
    append_screen_rect_packet(left, top, right, bottom, 0x80000000, 1);
    {
        int st = hud_star_height * 0xEA0;
        h = hud_star_height;
        top = (pos[1] + e->unk4A) << 4;
        top += (h * 0xF40) / 256;
        bh = (e->unk74 * st) / (e->unk08 << 8);
        append_screen_rect_packet(left, top, right, top - bh, 0x80829E00, 1);
    }
    i = 1;
    if (i < e->unk74)
        do {
            int hh = hud_star_height;
            top = (pos[1] + e->unk4A) << 4;
            top += (hh * 0xF40) / 256;
            step = hud_star_height * 0xEA0;
            step = i * step / (e->unk08 << 8);
            i++;
            top -= step;
            top -= 16;
            append_screen_rect_packet(left, top, right, top + 32, 0x80000000, 1);
        } while (i < e->unk74);
    w = GetIconFrame(*(int *)e, 0);
    draw_rotated_hud_sprite(w, pos[0] + e->unk48, pos[1] + e->unk4A, hud_stars_width, hud_star_height, 0x80);
    return e->w;
}
