/* Steps a HUD element: clamps the shown value to 0..max, then on a random timer ramps its two-stage counter up to the limits or back down. Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/ui/hud/0023b120.c, FUN_L00_0023cdb8. */
void func_L00_0023D750_r(O23D750 *p) {
    u8 *c = p->c;
    s32 v = *p->src;
    p->val = v;
    if (p->max < v)
        p->val = p->max;
    else if (v < 0)
        p->val = 0;
    if (p->timer >= scale_ticks(5)) {
        p->timer = scale_ticks(5);
        if (c[0] < D_L00_0015F9F4_23D750)
            c[0]++;
        else if (c[1] < D_L00_0015F9F8_23D750)
            c[1]++;
    } else {
        p->f6C = 1;
        if (c[1] != 0)
            c[1]--;
        else if (c[0] != 0)
            c[0]--;
        else
            p->f6C = -6;
    }
}
